from lib import *
S = SS('x25')
steps = [
    step("默认调度器上的一个快任务(fixedRate 200 ms,耗时 5 ms)和一个慢任务(每 3 s 一次,耗时 1000 ms),全部在 pool-1-thread-1 这一个线程上执行。快任务在 104、297、499 ms 正常触发;慢任务 506 ms 开始,占了线程 1000 ms;这期间快任务一次也没跑,等慢任务结束(1506 ms 左右)后,快任务在 1511、1517、1528、1534、1541 ms 连着补跑了 5 次,然后才恢复每 200 ms 一次。单线程调度器上一个慢任务会挡住所有别的定时任务,之后还会一口气补上错过的次数。", t=tl(S(1)), mark=lidx(S(1), '506 ms  slow', '1511 ms  fast', '1541 ms  fast'), done=lidx(S(1), '104 ms  fast', '297 ms  fast', '499 ms  fast'), b=bars([['调度线程数', 1, '1(pool-1-thread-1)'], ['慢任务占用线程 ms', 1000, '1000'], ['慢任务期间快任务错过的次数', 5, '5'], ['结束后 30 ms 内补跑的次数', 5, '5']], 1000, done=[0], cur=[1], mark=[2, 3]), kv=KV([['线程', '只有 1 个'], ['慢任务期间', '快任务全部被挡住'], ['结束之后', '30 ms 内补跑 5 次'], ['风险', '一个慢任务拖住所有定时任务']], ['风险'])),
    step("同样的两个任务,把调度器线程池大小设成 3(线程名 sched-1、sched-2...):慢任务 500 ms 开始占用 sched-2,快任务在 108、304、500、703、904、1104、1304 ms ... 一直按每 200 ms 左右触发,没有被挡住,也没有补跑。", t=tl(S(2)), mark=lidx(S(2), '500 ms  slow'), done=lidx(S(2), '108 ms  fast', '703 ms  fast', '1104 ms  fast'), b=bars([['调度线程数', 3, '3'], ['慢任务期间快任务错过的次数', 0, '0']], 3, done=[0, 1]), kv=KV([['线程池大小', '3'], ['慢任务', '占 sched-2 一个线程'], ['快任务', '继续按 200 ms 触发'], ['补跑', '没有']], ['线程池大小'])),
    step("Spring Boot 里同样的两个任务:容器里有一个 taskScheduler Bean,线程名是 scheduling-1,行为和纯 Spring 的默认一样,是单线程:慢任务从 507 ms 占到 1507 ms,快任务在 1511、1518、1524、1530、1537 ms 连着补跑 5 次。Boot 的默认 TaskScheduler 池大小也是 1。", t=tl(S(3)), mark=lidx(S(3), '507 ms  slow'), done=lidx(S(3), 'Boot 里的 TaskScheduler Bean', '106 ms  fast'), b=bars([['Boot 默认调度线程数', 1, '1(scheduling-1)'], ['慢任务期间快任务错过的次数', 5, '5']], 5, done=[0], mark=[1]), kv=KV([['Boot 的 TaskScheduler', 'taskScheduler,线程 scheduling-1'], ['池大小', '1'], ['现象', '同样被慢任务挡住并补跑'], ['改法', 'spring.task.scheduling.pool.size,这篇没有测']], ['现象'])),
    step("任务比间隔还慢时。fixedRate = 300 ms、任务耗时 500 ms:开始时刻是 2、509、1015、1520、2025、2530 ms,实际周期约 506 ms(没有重叠,上一次一结束下一次立刻开始),3 s 内跑了 6 次。fixedDelay = 300 ms、耗时 500 ms:开始时刻是 2、814、1620、2426 ms,周期约 806 ms(500 加 300),3 s 内跑了 4 次。fixedRate 按开始时间算间隔,fixedDelay 按上一次结束时间算。", t=tl(S(4)), mark=lidx(S(4), '2530 ms  fixedRate', '2426 ms  fixedDelay'), done=lidx(S(4), '509 ms  fixedRate', '814 ms  fixedDelay'), b=bars([['fixedRate 3 s 内跑的次数', 6, '6(周期约 506 ms)'], ['fixedDelay 3 s 内跑的次数', 4, '4(周期约 806 ms)']], 6, cur=[0], mark=[1]), kv=KV([['fixedRate', '按开始时间算,忙不过来就背靠背'], ['fixedDelay', '按上次结束时间再等 300 ms'], ['周期', '约 506 ms 对约 806 ms'], ['是否重叠', '单线程下都不重叠']], ['是否重叠'])),
    step("任务抛异常。fixedRate = 300 ms,第 2 次抛 IllegalStateException:Spring 记一条 ERROR 日志(TaskUtils$LoggingErrorHandler:Unexpected error occurred in scheduled task),后面的 boom#3 到 boom#7 照常在 601、904、1202、1505、1805 ms 继续执行。重复调度的任务抛异常不会让后续调度停掉。", t=tl(S(5)), mark=lidx(S(5), 'LoggingErrorHandler', '301 ms  boom#2'), done=lidx(S(5), '601 ms  boom#3', '1805 ms  boom#7'), b=bars([['抛异常的次数', 1, '1'], ['抛异常之后继续执行的次数', 5, '5(boom#3 到 boom#7)']], 5, mark=[0], done=[1]), kv=KV([['异常', '记 ERROR 日志'], ['后续调度', '不受影响'], ['日志', 'TaskUtils$LoggingErrorHandler'], ['建议', '任务里自己 try/catch,并上报']], ['后续调度'])),
    step("@Scheduled 加 @Async(fixedRate = 200 ms,每次耗时 700 ms)。任务不再被串行:每次触发都交给 @Async 的执行器,在 SimpleAsyncTaskExecutor-1 到 -8 这些新线程上同时跑,1.5 s 内触发了 8 次(110、299、503、703、903、1102、1303、1498 ms),它们互相重叠,没有任何防重叠。纯 Spring 默认的 @Async 每次新建线程,慢任务堆积时线程数会一直涨。", t=tl(S(6)), mark=lidx(S(6), 'SimpleAsyncTaskExecutor-8'), done=lidx(S(6), 'SimpleAsyncTaskExecutor-1', 'SimpleAsyncTaskExecutor-4'), b=bars([['1.5 s 内触发的次数', 8, '8'], ['使用的线程数', 8, '8(每次新线程)'], ['任务耗时 ms', 700, '700(触发间隔 200 ms)']], 700, cur=[0], mark=[1], done=[2]), kv=KV([['@Scheduled + @Async', '触发和执行分开'], ['线程', '纯 Spring 默认每次新建'], ['重叠', '没有防护'], ['建议', '配有界线程池,或者加分布式锁/互斥']], ['重叠'])),
]
A = mkartx('x25', 25, 'Spring,Scheduled,定时任务,fixedRate,fixedDelay,真实验证,动画演示',
    '实测 @Scheduled:默认调度器只有一个线程(纯 Spring 的 pool-1-thread-1、Boot 的 scheduling-1),一个耗时 1000 ms 的慢任务让每 200 ms 的快任务错过 5 次并在结束后 30 ms 内补跑 5 次;线程池设成 3 就不互相挡;fixedRate 与 fixedDelay 在任务比间隔慢时周期约 506 ms 对约 806 ms;任务抛异常不影响后续调度;加 @Async 会重叠执行。',
    '@Scheduled 的任务到底跑在哪个线程?一个慢任务会不会挡住别的任务?fixedRate 和 fixedDelay 在任务变慢时有什么区别?任务抛异常会怎样?加上 @Async 呢?这篇在 Spring Framework 7.0.9 上用带时间戳的日志逐项验证。',
    [('1 个线程', '纯 Spring 与 Boot 默认的调度器线程数(慢任务期间其它定时任务全被挡住)'), ('5 次', '一个 1000 ms 的慢任务结束后,被挡住的 fixedRate = 200 ms 任务在 30 ms 内补跑的次数'), ('506 对 806 ms', '任务耗时 500 ms、间隔 300 ms 时,fixedRate 与 fixedDelay 的实际周期')],
    [('默认单线程', '<p>慢任务挡住所有任务,结束后一口气补跑错过的次数。</p>'),
     ('加大线程池', '<p>调度器线程池大小设成 3,快任务不再被挡。</p>'),
     ('Boot 的默认', '<p>Boot 的 taskScheduler 池大小也是 1。</p>'),
     ('fixedRate 与 fixedDelay', '<p>任务比间隔慢时,fixedRate 背靠背执行,fixedDelay 在每次结束后再等。</p>'),
     ('异常', '<p>抛异常只记日志,后续调度继续。</p>'),
     ('@Async', '<p>触发和执行分开,执行会重叠,线程可能无限增长。</p>')],
    steps,
    [ENV_X + '。第一、二、四、五、六节用不带 Boot 的 Spring Framework 7.0.9,第三节用 Spring Boot 4.0.8 的 @EnableAutoConfiguration;时间戳每次运行有几 ms 的抖动,补跑的具体次数取决于被挡住的时长(这次是 5 次)',
     '没有验证:cron 表达式的触发精度与时区;多实例部署下同一个任务的重复执行(见后面的 ShedLock 篇);spring.task.scheduling.* 配置项;ScheduledTaskRegistrar 的动态注册;应用关闭时正在执行的定时任务(见优雅停机篇);调度器线程池的 shutdown 等待时间'],
    '@Scheduled')
